/**
 * Zentrale Modul-Registry (Umsetzungsplan Phase 0, AP 0.4).
 *
 * EINZIGE Quelle für: Menü (gruppe/label/icon), Suchbegriffe (suche), Meta-Beschreibungen (meta),
 * Modulübersicht/Baum (baum + BAUM_GRUPPEN), Direktlink-Aliase (TAB_ALIASES) und die Sitemap
 * (scripts/gen-sitemap.ts). Neue Module ausschließlich hier eintragen; tests/registry.test.ts
 * prüft die Konsistenz in der CI.
 *
 * Einträge ohne `gruppe` erscheinen nicht im Menü, sind aber per Direktlink (#id) erreichbar.
 * Icons sind lucide-Namen; die Zuordnung zu Komponenten liegt in ./icons.ts.
 */

export type ModulTyp = 'calculator' | 'database' | 'quiz' | 'standard' | 'info' | 'norm';

export interface BaumInfo {
  /** Titel in der Modulübersicht */
  titel: string;
  typ: ModulTyp;
  /** Kurzbeschreibung in der Modulübersicht */
  kurz: string;
  icon: string;
  norm?: string;
}

export interface ModulEintrag {
  id: string;
  /** Beschriftung im Menü */
  label: string;
  icon: string;
  /** Menügruppe; fehlt = nur Direktlink */
  gruppe?: NavGruppe;
  baum?: BaumInfo;
  /** Meta-Description (SEO) */
  meta?: string;
  /** Zusätzliche Suchbegriffe für die Menüsuche */
  suche?: readonly string[];
}

